package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.*; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/dashboard") public class AdminDashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{req.setAttribute("productCount",new ProductDAO().countAll());req.setAttribute("categoryCount",new CategoryDAO().countAll());req.setAttribute("userCount",new UserDAO().countAll());OrderDAO od=new OrderDAO();req.setAttribute("orderCount",od.countAll());req.setAttribute("pendingCount",od.countPending());req.getRequestDispatcher("/WEB-INF/views/admin/dashboard.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}}
